import React from 'react';

export interface Project {
  id: number;
  title: string;
  category: 'Fashion' | 'Commercial' | 'Social' | 'Event';
  client: string;
  year: string;
  image: string; // Main Hero Image
  description: string;
  challenge: string;
  solution: string;
  credits: { role: string; name: string }[];
  gallery: string[]; // Additional images
}

export interface Service {
  id: string;
  title: string;
  shortDesc: string;
  fullDesc: string;
  image: string;
  capabilities: string[];
}

export enum PageState {
  HOME = 'HOME',
  WORK = 'WORK',
  ABOUT = 'ABOUT',
  CONTACT = 'CONTACT',
  PROJECT_DETAIL = 'PROJECT_DETAIL',
  SERVICE_DETAIL = 'SERVICE_DETAIL',
  ADMIN = 'ADMIN'
}

export interface AIGeneratedConcept {
  conceptTitle: string;
  visualDirection: string;
  colorPalette: string[];
  suggestedShotList: string[];
}

import React, { useState } from 'react';
import { Copy, Check, Terminal, Plus, Image as ImageIcon } from 'lucide-react';

export const Admin: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [password, setPassword] = useState('');
  const [activeTab, setActiveTab] = useState<'PROJECT' | 'SERVICE'>('PROJECT');

  // Project Form State
  const [formData, setFormData] = useState({
    id: Math.floor(Math.random() * 1000), // Random ID suggestion
    title: '',
    client: '',
    category: 'Fashion',
    year: new Date().getFullYear().toString(),
    image: '',
    description: '',
    challenge: '',
    solution: '',
    creditsRole1: 'Director',
    creditsName1: '',
    creditsRole2: 'Photographer',
    creditsName2: '',
    gallery1: '',
    gallery2: ''
  });

  const [copied, setCopied] = useState(false);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    // Simple client-side protection. In a real app, use backend auth.
    // Password is: p2p2024
    if (password === 'p2p2024') {
      setIsAuthenticated(true);
    } else {
      alert('Incorrect Password');
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  // Generate the formatted code string
  const generateCode = () => {
    return `  {
    id: ${formData.id},
    title: "${formData.title}",
    category: "${formData.category}",
    client: "${formData.client}",
    year: "${formData.year}",
    image: "${formData.image}",
    description: "${formData.description}",
    challenge: "${formData.challenge}",
    solution: "${formData.solution}",
    credits: [
        { role: "${formData.creditsRole1}", name: "${formData.creditsName1}" },
        { role: "${formData.creditsRole2}", name: "${formData.creditsName2}" }
    ],
    gallery: [
        "${formData.gallery1}",
        "${formData.gallery2}"
    ]
  },`;
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(generateCode());
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-p2p-black flex items-center justify-center px-6">
        <div className="w-full max-w-md bg-white/5 border border-white/10 p-12 text-center">
          <h2 className="text-2xl font-serif text-white mb-6">Studio Internal</h2>
          <form onSubmit={handleLogin} className="space-y-4">
            <input 
              type="password" 
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-black border border-white/20 p-3 text-white focus:border-p2p-accent outline-none text-center tracking-widest"
              placeholder="ENTER PASSWORD"
            />
            <button className="w-full bg-white text-black py-3 uppercase tracking-widest text-xs font-bold hover:bg-p2p-accent hover:text-white transition-all">
              Access
            </button>
            <p className="text-xs text-gray-600 mt-4">Default: p2p2024</p>
          </form>
        </div>
      </div>
    );
  }

  return (
    <section className="min-h-screen bg-p2p-black pt-32 pb-24 text-white">
      <div className="max-w-[1920px] mx-auto px-6 md:px-12">
        <div className="flex items-center justify-between mb-12 border-b border-white/10 pb-6">
          <h1 className="text-3xl font-serif">Content Manager</h1>
          <div className="flex gap-4">
            <button 
              onClick={() => setActiveTab('PROJECT')}
              className={`text-xs uppercase tracking-widest px-4 py-2 ${activeTab === 'PROJECT' ? 'bg-white text-black' : 'border border-white/20 text-gray-400'}`}
            >
              New Project
            </button>
            {/* Future expansion: Service editor */}
            <button 
              disabled
              className="text-xs uppercase tracking-widest px-4 py-2 border border-white/10 text-gray-600 cursor-not-allowed"
            >
              New Service (Soon)
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">

          {/* Form Side */}
          <div className="space-y-8 animate-fade-in">
            <div className="bg-white/5 p-8 border border-white/10">
              <h3 className="text-xs uppercase tracking-widest text-p2p-accent mb-6 flex items-center gap-2">
                <Plus size={16} /> Project Details
              </h3>

              <div className="grid grid-cols-2 gap-6 mb-6">
                <div>
                  <label className="block text-xs text-gray-500 mb-2 uppercase">Project Title</label>
                  <input name="title" value={formData.title} onChange={handleInputChange} className="w-full bg-black border border-white/20 p-3 text-sm focus:border-white outline-none" placeholder="e.g. Urban Silence" />
                </div>
                <div>
                  <label className="block text-xs text-gray-500 mb-2 uppercase">Client</label>
                  <input name="client" value={formData.client} onChange={handleInputChange} className="w-full bg-black border border-white/20 p-3 text-sm focus:border-white outline-none" placeholder="e.g. Theory" />
                </div>
                <div>
                  <label className="block text-xs text-gray-500 mb-2 uppercase">Category</label>
                  <select name="category" value={formData.category} onChange={handleInputChange} className="w-full bg-black border border-white/20 p-3 text-sm focus:border-white outline-none">
                    <option value="Fashion">Fashion</option>
                    <option value="Commercial">Commercial</option>
                    <option value="Social">Social</option>
                    <option value="Event">Event</option>
                  </select>
                </div>
                <div>
                  <label className="block text-xs text-gray-500 mb-2 uppercase">Year</label>
                  <input name="year" value={formData.year} onChange={handleInputChange} className="w-full bg-black border border-white/20 p-3 text-sm focus:border-white outline-none" />
                </div>
              </div>

              <div className="space-y-6">
                <div>
                  <label className="block text-xs text-gray-500 mb-2 uppercase flex items-center gap-2">
                    <ImageIcon size={14} /> Main Image URL
                  </label>
                  <input name="image" value={formData.image} onChange={handleInputChange} className="w-full bg-black border border-white/20 p-3 text-sm focus:border-white outline-none" placeholder="https://..." />
                  <p className="text-[10px] text-gray-600 mt-1">Use /images/filename.jpg for local or https:// for web</p>
                </div>

                <div>
                  <label className="block text-xs text-gray-500 mb-2 uppercase">Short Description</label>
                  <textarea name="description" value={formData.description} onChange={handleInputChange} className="w-full bg-black border border-white/20 p-3 text-sm focus:border-white outline-none h-20" placeholder="One sentence summary..." />
                </div>

                <div className="grid grid-cols-2 gap-6">
                   <div>
                    <label className="block text-xs text-gray-500 mb-2 uppercase">Challenge</label>
                    <textarea name="challenge" value={formData.challenge} onChange={handleInputChange} className="w-full bg-black border border-white/20 p-3 text-sm focus:border-white outline-none h-24" />
                   </div>
                   <div>
                    <label className="block text-xs text-gray-500 mb-2 uppercase">Solution</label>
                    <textarea name="solution" value={formData.solution} onChange={handleInputChange} className="w-full bg-black border border-white/20 p-3 text-sm focus:border-white outline-none h-24" />
                   </div>
                </div>

                {/* Credits */}
                <div className="border-t border-white/10 pt-6">
                  <label className="block text-xs text-p2p-accent mb-4 uppercase">Team Credits</label>
                  <div className="grid grid-cols-2 gap-4 mb-2">
                    <input name="creditsRole1" value={formData.creditsRole1} onChange={handleInputChange} className="bg-black border border-white/20 p-2 text-xs" placeholder="Role 1" />
                    <input name="creditsName1" value={formData.creditsName1} onChange={handleInputChange} className="bg-black border border-white/20 p-2 text-xs" placeholder="Name 1" />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <input name="creditsRole2" value={formData.creditsRole2} onChange={handleInputChange} className="bg-black border border-white/20 p-2 text-xs" placeholder="Role 2" />
                    <input name="creditsName2" value={formData.creditsName2} onChange={handleInputChange} className="bg-black border border-white/20 p-2 text-xs" placeholder="Name 2" />
                  </div>
                </div>

                 {/* Gallery */}
                <div className="border-t border-white/10 pt-6">
                  <label className="block text-xs text-p2p-accent mb-4 uppercase">Gallery Images</label>
                  <div className="space-y-2">
                    <input name="gallery1" value={formData.gallery1} onChange={handleInputChange} className="w-full bg-black border border-white/20 p-2 text-xs" placeholder="Gallery Image URL 1" />
                    <input name="gallery2" value={formData.gallery2} onChange={handleInputChange} className="w-full bg-black border border-white/20 p-2 text-xs" placeholder="Gallery Image URL 2" />
                  </div>
                </div>

              </div>
            </div>
          </div>

          {/* Code Output Side */}
          <div className="relative group">
            <div className="sticky top-32">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-xs uppercase tracking-widest text-gray-500 flex items-center gap-2">
                  <Terminal size={16} /> Generated Code
                </h3>
                <span className="text-[10px] text-gray-600">data/projects.ts</span>
              </div>

              <div className="bg-gray-900 rounded-md overflow-hidden border border-white/10 shadow-2xl relative">
                <div className="absolute top-4 right-4 z-10">
                   <button 
                    onClick={handleCopy}
                    className={`flex items-center gap-2 px-4 py-2 text-xs font-bold uppercase tracking-wider transition-all rounded ${copied ? 'bg-green-500 text-black' : 'bg-white text-black hover:bg-gray-200'}`}
                   >
                     {copied ? <Check size={14} /> : <Copy size={14} />}
                     {copied ? 'Copied!' : 'Copy Code'}
                   </button>
                </div>

                <div className="p-6 overflow-x-auto">
                  <pre className="font-mono text-xs md:text-sm text-green-400 leading-relaxed whitespace-pre-wrap">
                    {generateCode()}
                  </pre>
                </div>
              </div>

              <div className="mt-8 p-6 bg-white/5 border border-white/10 text-gray-400 text-sm leading-relaxed">
                <p className="font-bold text-white mb-2">Instructions:</p>
                <ol className="list-decimal pl-4 space-y-2">
                  <li>Fill out the form on the left.</li>
                  <li>Click <strong>Copy Code</strong> above.</li>
                  <li>Go to your GitHub repository (press <code>.</code> on keyboard).</li>
                  <li>Open <code>data/projects.ts</code>.</li>
                  <li>Paste this code at the bottom of the list (before the closing <code>];</code>).</li>
                </ol>
              </div>
            </div>
          </div>

        </div>
      </div>
    </section>
  );
};

import React, { useState, useEffect } from 'react';
import { Navigation } from './components/Navigation';
import { Portfolio } from './components/Portfolio';
import { Services } from './components/Services';
import { About } from './components/About';
import { Contact } from './components/Contact';
import { AICreativeDirector } from './components/AICreativeDirector';
import { Footer } from './components/Footer';
import { ProjectDetail } from './components/ProjectDetail';
import { ServiceDetail } from './components/ServiceDetail';
import { Admin } from './components/Admin';
import { PageState } from './types';
import { ArrowDown } from 'lucide-react';
import { projects } from './data/projects';
import { services } from './data/services';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<PageState>(PageState.HOME);
  const [selectedProjectId, setSelectedProjectId] = useState<number | null>(null);
  const [selectedServiceId, setSelectedServiceId] = useState<string | null>(null);

  // Helper to handle scrolling behavior on navigation
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [currentPage]);

  const handleProjectClick = (id: number) => {
    setSelectedProjectId(id);
    setCurrentPage(PageState.PROJECT_DETAIL);
  };

  const handleServiceClick = (id: string) => {
    setSelectedServiceId(id);
    setCurrentPage(PageState.SERVICE_DETAIL);
  };

  const handleNextProject = () => {
    if (!selectedProjectId) return;
    const currentIndex = projects.findIndex(p => p.id === selectedProjectId);
    const nextIndex = (currentIndex + 1) % projects.length;
    setSelectedProjectId(projects[nextIndex].id);
  };

  const getSelectedProject = () => {
    return projects.find(p => p.id === selectedProjectId) || projects[0];
  };

  const getSelectedService = () => {
    return services.find(s => s.id === selectedServiceId) || services[0];
  };

  // Helper to render current view
  const renderContent = () => {
    switch(currentPage) {
      case PageState.ADMIN:
        return <Admin />;
      case PageState.PROJECT_DETAIL:
        return (
          <ProjectDetail 
            project={getSelectedProject()} 
            onBack={() => setCurrentPage(PageState.WORK)}
            onNext={handleNextProject}
          />
        );
      case PageState.SERVICE_DETAIL:
        return (
          <ServiceDetail 
            service={getSelectedService()}
            onBack={() => setCurrentPage(PageState.ABOUT)} // Returns to About page where services are listed
          />
        );
      case PageState.WORK:
        return (
          <div className="animate-fade-in pt-32">
             <Portfolio onProjectClick={handleProjectClick} />
          </div>
        );
      case PageState.ABOUT:
        return (
          <div className="animate-fade-in pt-32">
            <About />
            <Services onServiceClick={handleServiceClick} />
          </div>
        );
      case PageState.CONTACT:
        return (
          <div className="animate-fade-in pt-32">
            <Contact />
          </div>
        );
      case PageState.HOME:
      default:
        return (
          <main className="animate-fade-in">
            {/* Artistic Hero Section */}
            <section className="relative h-screen w-full flex items-center overflow-hidden bg-p2p-black">
              {/* Background with grain/texture overlay could go here */}
              <div className="absolute inset-0 z-0 opacity-40">
                <img 
                  src="https://images.unsplash.com/photo-1492633423870-43d1cd2775eb?q=80&w=2070&auto=format&fit=crop" 
                  alt="Background" 
                  className="w-full h-full object-cover grayscale brightness-50 scale-105 animate-[fadeIn_3s_ease-out_forwards]"
                />
              </div>

              <div className="relative z-10 w-full max-w-[1920px] mx-auto px-6 md:px-12 grid grid-cols-12 gap-6 h-full items-end pb-32 md:pb-40">

                {/* Hero Text */}
                <div className="col-span-12 md:col-span-8 lg:col-span-9">
                  <div className="reveal-container">
                    <h2 className="text-white text-xs md:text-sm uppercase tracking-[0.4em] mb-4 reveal-text delay-100 text-p2p-gray">
                      Creative Production Studio
                    </h2>
                  </div>
                  <div className="reveal-container">
                    <h1 className="text-6xl md:text-8xl lg:text-9xl font-serif text-white leading-[0.9] reveal-text delay-200">
                      Visuals
                    </h1>
                  </div>
                  <div className="reveal-container">
                    <h1 className="text-6xl md:text-8xl lg:text-9xl font-serif text-white leading-[0.9] reveal-text delay-300 italic">
                      That Transcend
                    </h1>
                  </div>
                  <div className="reveal-container">
                     <h1 className="text-6xl md:text-8xl lg:text-9xl font-serif text-white leading-[0.9] reveal-text delay-500">
                      Borders.
                    </h1>
                  </div>
                </div>

                {/* Subtext / CTA */}
                <div className="col-span-12 md:col-span-4 lg:col-span-3 flex flex-col justify-end">
                   <div className="opacity-0 animate-[fadeIn_1s_ease-out_1.2s_forwards]">
                      <p className="text-gray-400 text-sm leading-relaxed mb-8 max-w-xs">
                        Pair to Pair connects brands with global audiences through high-fidelity aesthetics, cultural strategy, and production-first methodology.
                      </p>
                      <button 
                        onClick={() => setCurrentPage(PageState.WORK)}
                        className="group flex items-center gap-4 text-white uppercase tracking-widest text-xs hover:text-gray-300 transition-colors"
                      >
                        View Cases <span className="w-8 h-[1px] bg-white group-hover:w-12 transition-all"></span>
                      </button>
                   </div>
                </div>
              </div>

              {/* Scroll Indicator */}
              <div className="absolute bottom-12 left-1/2 transform -translate-x-1/2 opacity-0 animate-[fadeIn_1s_ease-out_2s_forwards]">
                <ArrowDown className="text-white/30 animate-bounce" size={24} />
              </div>
            </section>

            <Portfolio onProjectClick={handleProjectClick} />
            <Services onServiceClick={handleServiceClick} />
            <AICreativeDirector />
            <About />
            <Contact />
          </main>
        );
    }
  };

  return (
    <div className="min-h-screen bg-p2p-black text-white font-sans selection:bg-white selection:text-black">
      <Navigation currentPage={currentPage} setPage={setCurrentPage} />
      {renderContent()}
      <Footer setPage={setCurrentPage} />
    </div>
  );
};

export default App;

