          required: ["conceptTitle", "visualDirection", "colorPalette", "suggestedShotList"]
        }
      }
    });

    const text = response.text;
    if (!text) return null;

    return JSON.parse(text) as AIGeneratedConcept;

  } catch (error) {
    console.error("Error generating creative brief:", error);
    return null;
  }
};

